const { withXcodeProject } = require('expo/config-plugins');

/** Apple Developer Team. Not a secret — it appears in every signed binary. */
const DEVELOPMENT_TEAM = 'TF884Z27XZ';

/**
 * ios/ is gitignored and regenerated by `expo prebuild`, so the signing team
 * picked in Xcode is wiped every time — the archive then fails with "Signing
 * for Stopper requires a development team". Same failure mode that lost the
 * pod deployment-target floor, the Game Center setting and the build number.
 *
 * Stamps the team and automatic signing into every build configuration so a
 * fresh prebuild comes out archivable.
 */
module.exports = function withSigningTeam(config) {
  return withXcodeProject(config, (cfg) => {
    const project = cfg.modResults;
    const configurations = project.pbxXCBuildConfigurationSection();

    for (const key of Object.keys(configurations)) {
      const entry = configurations[key];
      // Section objects are interleaved with `<key>_comment` strings.
      if (typeof entry !== 'object' || !entry.buildSettings) continue;
      // Only the app target carries a product name; pods must be left alone.
      if (!entry.buildSettings.PRODUCT_BUNDLE_IDENTIFIER) continue;

      entry.buildSettings.DEVELOPMENT_TEAM = `"${DEVELOPMENT_TEAM}"`;
      entry.buildSettings.CODE_SIGN_STYLE = 'Automatic';
    }

    return cfg;
  });
};
